const rows = $input.all().map(i => i.json);
const ahora = new Date();
const hace7dias = new Date(ahora.getTime() - 7 * 24 * 60 * 60 * 1000);
const recientes = rows.filter(r => r.fecha && new Date(r.fecha) >= hace7dias && new Date(r.fecha) <= ahora);

const porMateria = {};
const porTutor = {};
recientes.forEach(r => {
  if (r.materia) porMateria[r.materia] = (porMateria[r.materia] || 0) + 1;
  if (r.id_tutor) porTutor[r.id_tutor] = (porTutor[r.id_tutor] || 0) + 1;
});

let topMateria = 'N/D';
let topMateriaCount = 0;
Object.entries(porMateria).forEach(([m, c]) => { if (c > topMateriaCount) { topMateria = m; topMateriaCount = c; } });

let topTutor = 'N/D';
let topTutorCount = 0;
Object.entries(porTutor).forEach(([t, c]) => { if (c > topTutorCount) { topTutor = t; topTutorCount = c; } });

const fmt = d => d.toISOString().slice(0, 10);

const mensaje = `
<div style="font-family: Arial, Helvetica, sans-serif; max-width: 560px; margin: 0 auto; color: #333;">
  <div style="background: #2c3e50; color: #ffffff; padding: 24px; border-radius: 10px 10px 0 0;">
    <h1 style="margin: 0; font-size: 20px;">Reporte Semanal · TutorBot</h1>
    <p style="margin: 6px 0 0; font-size: 13px; color: #cfd8e3;">${fmt(hace7dias)} al ${fmt(ahora)}</p>
  </div>
  <div style="border: 1px solid #e2e2e2; border-top: none; padding: 24px; border-radius: 0 0 10px 10px;">
    <table style="width: 100%; border-collapse: collapse; font-size: 14px;">
      <tr>
        <td style="padding: 10px 0; color: #666;">Total de tutorias en la semana</td>
        <td style="padding: 10px 0; text-align: right; font-weight: bold; font-size: 16px;">${recientes.length}</td>
      </tr>
      <tr style="border-top: 1px solid #eee;">
        <td style="padding: 10px 0; color: #666;">Materia con mas tutorias</td>
        <td style="padding: 10px 0; text-align: right; font-weight: bold;">${topMateria} <span style="color:#999; font-weight: normal;">(${topMateriaCount})</span></td>
      </tr>
      <tr style="border-top: 1px solid #eee;">
        <td style="padding: 10px 0; color: #666;">Tutor con mas tutorias</td>
        <td style="padding: 10px 0; text-align: right; font-weight: bold;">${topTutor} <span style="color:#999; font-weight: normal;">(${topTutorCount})</span></td>
      </tr>
    </table>
    <p style="margin: 24px 0 0; font-size: 12px; color: #999; border-top: 1px solid #eee; padding-top: 12px;">TutorBot · Reporte generado automaticamente cada lunes</p>
  </div>
</div>
`.trim();

return [{ json: { mensaje } }];
